import java.util.List;
import java.util.stream.Stream;

public class Pipeline {
    public static void main(String[] args) {
        List<Double> celsius = List.of(21.5, -999.0, 19.0, 23.5);   // -999 = sensor error.

        List<Double> fahrenheit = celsius.stream()                 // source.
            .filter(c -> c > -100)                                  // lazy: keep valid.
            .map(c -> c * 9 / 5 + 32)                               // lazy: convert.
            .toList();                                              // terminal: runs it all.
        System.out.println(fahrenheit);          // [70.7, 66.2, 74.3]
        System.out.println(celsius.size());      // 4: source unchanged.

        Stream<Double> once = celsius.stream();
        System.out.println(once.count());        // 4
        try { once.toList(); }
        catch (IllegalStateException e) { System.out.println("already used"); }
    }
}
```

